  KEY `idx_missione`(`codice_missione`),
  CONSTRAINT `fk_pvc_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

