CREATE TABLE IF NOT EXISTS `plp_packs_catalog` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `codice`         VARCHAR(50) NOT NULL,
  `nome`           VARCHAR(100) NOT NULL,
